contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(string calldata description) public payable {
        require(msg.sender != address(this), "caller is InvMutTest");
        require(bytes(description).length > 0, "description must not be empty");

        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == true);
    }

    receive() external payable {}
}

